const GardenLayout=(()=>{
  const zones=['sill','path'];
  const legacyZones={bench:'sill',shelf:'sill',pond:'path',meadow:'path'};
  const scenes={campus:'校园植物园',terrace:'屋顶露台',courtyard:'中式庭院',starlight:'繁星之夜'};
  const weather={sunny:'晴天',rain:'细雨',snow:'飘雪'};
  const props={bench:'木长椅',lantern:'庭园灯',rock:'景石',arch:'花架拱门',planter:'装饰花槽',terrarium:'玻璃生态箱',worktable:'园艺操作台',plantstand:'三层盆栽架',wateringcan:'珐琅浇水壶',teatable:'庭院茶桌',steppingstones:'苔石步道',fence:'木栅栏',fountain:'双层石泉'};
  const propRadii={bench:.90,lantern:.36,rock:.62,arch:1.03,planter:.55,terrarium:.64,worktable:.84,plantstand:.66,wateringcan:.70,teatable:.48,steppingstones:.76,fence:.80,fountain:.61};
  const empty=()=>({scene:'campus',weather:'sunny',decorations:[]});
  function unpack(value){
    const records=Array.isArray(value)?value:value?.records||[],design=value?.design||empty();
    const all=[...records,...design.decorations],moved=new Map();
    const occupied=all.filter(p=>zones.includes(p.zone)).map(located);
    for(const p of all){
      if(!Object.hasOwn(legacyZones,p.zone))continue;
      const item={...p,zone:legacyZones[p.zone]};
      Object.assign(item,place(item,occupied,located(p)));
      occupied.push(item);moved.set(p,item);
    }
    const convert=p=>moved.get(p)||p;
    return {records:records.map(convert),design:{...design,decorations:design.decorations.map(convert)}};
  }
  function radius(p){
    if(p.kind)return propRadii[p.kind]*(p.scale??1);
    return ((legacyZones[p.zone]||p.zone)==='sill'?{small:.454,medium:.625,large:.867}:{small:.637,medium:1.043,large:1.455})[p.size]||1.043;
  }
  function legacyPoint(n){
    if(!Number.isInteger(n)||n<=0)return {x:0,z:0};
    const side=Math.ceil((Math.sqrt(n+1)-1)/2),length=side*2,offset=(2*side+1)**2-1-n;
    const edge=Math.floor(offset/length),i=offset%length;
    const [x,z]=[[side-i,side],[-side,side-i],[-side+i,-side],[side,-side+i]][edge];
    return {x:x*3,z:z*3};
  }
  function located(p){return Number.isFinite(p.x)&&Number.isFinite(p.z)?p:{...p,...legacyPoint(p.slot)}}
  function clear(p,list){
    return !list.some(q=>{
      if(q.zone!==p.zone||q.uid===p.uid&&p.uid)return false;
      const other=located(q);
      return Math.hypot(other.x-p.x,other.z-p.z)<radius(p)+radius(q)-.00001;
    });
  }
  function place(p,list,preferred){
    if(preferred&&Number.isFinite(preferred.x)&&Number.isFinite(preferred.z)&&clear({...p,x:preferred.x,z:preferred.z},list))return {x:preferred.x,z:preferred.z};
    for(let n=0;n<10000;n++){
      const pt=legacyPoint(n);
      if(clear({...p,...pt},list))return pt;
    }
    throw Error('当前区域已满，请选择其他区域。');
  }
  function valid(records,design){
    if(!design||!Object.hasOwn(scenes,design.scene)||!Object.hasOwn(weather,design.weather)||!Array.isArray(design.decorations)||design.decorations.length>300)return false;
    const ids=new Set(),prior=[];
    for(const [index,p] of [...records,...design.decorations].entries()){
      if(!p||!zones.includes(p.zone)||typeof p.uid!=='string'||!p.uid||p.uid.length>400||ids.has(p.uid))return false;
      const decor=index>=records.length;
      if(decor?(!Object.hasOwn(props,p.kind)||Object.keys(p).some(k=>!['uid','kind','zone','x','z','rotation','scale'].includes(k))):('kind' in p))return false;
      if(p.x==null&&p.z==null&&!decor){if(!Number.isInteger(p.slot)||p.slot<0||p.slot>2000)return false}
      else if(![p.x,p.z].every(v=>Number.isFinite(v)&&Math.abs(v)<=160))return false;
      if(decor&&p.scale!==undefined&&(!Number.isFinite(p.scale)||p.scale<.5||p.scale>2))return false;
      if(!decor&&p.potStyle!==undefined&&!['clay','celadon','basalt'].includes(p.potStyle))return false;
      if(decor&&p.rotation!==undefined&&(!Number.isFinite(p.rotation)||Math.abs(p.rotation)>Math.PI*2))return false;
      const positioned=located(p);
      if(!clear(positioned,prior))return false;
      ids.add(p.uid);prior.push(positioned);
    }
    return true;
  }
  return {zones,scenes,weather,props,propRadii,empty,unpack,radius,located,clear,place,valid};
})();
globalThis.GardenLayout=GardenLayout;

const sessionName='__Host-flora_session';
export {authJson,nameKey,authQuota};
const sessionSeconds=30*86400;
const encoder=new TextEncoder();
const hex=bytes=>Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');
const randomKey=()=>hex(crypto.getRandomValues(new Uint8Array(32)));
const keyHash=async text=>hex(await crypto.subtle.digest('SHA-256',encoder.encode(text)));
const cookie=(name,value,seconds)=>name+'='+value+'; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age='+seconds;
const readCookie=(req,name)=>req.headers.get('Cookie')?.split(';').map(s=>s.trim()).find(s=>s.startsWith(name+'='))?.slice(name.length+1)||'';
function authJson(data,status=200,headers={}){
  return Response.json(data,{status,headers:{'Cache-Control':'private, no-store','Vary':'Cookie',...headers}});
}
const nameKey=async name=>'auth/names/'+await keyHash(name.toLowerCase());
async function sessionKey(request){
  const token=readCookie(request,sessionName);
  return /^[a-f0-9]{64}$/.test(token)?'auth/sessions/'+await keyHash(token):null;
}
export async function currentUser(request,env){
  const key=await sessionKey(request);
  if(!key)return null;
  const item=await env.BUCKET.get(key);
  if(!item)return null;
  const session=await item.json();
  if(session.until<=Date.now()){await env.BUCKET.delete(key);return null}
  const obj=await env.BUCKET.get(await nameKey(session.user.name));
  if(!obj)return null;
  const account=await obj.json();
  if(account.user.id!==session.user.id||account.revision!==session.revision)return null;
  return account.user;
}
async function startSession(user,env,revision){
  const token=randomKey();
  await env.BUCKET.put('auth/sessions/'+await keyHash(token),JSON.stringify({user,revision,until:Date.now()+sessionSeconds*1000}));
  return cookie(sessionName,token,sessionSeconds);
}
async function passwordKey(password,salt){
  const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']);
  return hex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:encoder.encode(salt),iterations:100000},key,256));
}
async function authQuota(req,env,action){
  const ip=req.headers.get('cf-connecting-ip')||'unknown';
  const key='auth/quota/'+await keyHash(ip+'|'+action);
  const now=Date.now(),limit=action==='register'?12:45;
  for(let i=0;i<4;i++){
    const obj=await env.BUCKET.get(key);
    let count=obj?await obj.json():null;
    if(!count||count.until<=now)count={until:now+600000,n:0};
    if(count.n>=limit)return false;
    count.n++;
    const ok=await env.BUCKET.put(key,JSON.stringify(count),{onlyIf:new Headers(obj?{'If-Match':obj.httpEtag}:{'If-None-Match':'*'})});
    if(ok)return true;
  }
  return false;
}
async function credentials(request,env,action){
  if(!request.headers.get('content-type')?.startsWith('application/json'))return authJson({error:'请求格式无效。'},415);
  if(!await authQuota(request,env,action))return authJson({error:'操作较频繁，请十分钟后再试。'},429);
  if(Number(request.headers.get('content-length'))>4096)return authJson({error:'输入过长。'},413);
  const body=await request.text();
  if(body.length>4096)return authJson({error:'输入过长。'},413);
  let input;try{input=JSON.parse(body)}catch{return authJson({error:'输入格式有误。'},400)}
  const owner=action==='password'?await currentUser(request,env):null;
  if(action==='password'&&!owner)return authJson({error:'请重新登录后修改密码。'},401);
  const name=owner?owner.name:typeof input?.name==='string'?input.name.trim().normalize('NFKC'):'';
  const password=input?.password;
  if(!/^[\p{L}\p{N}_-]{2,24}$/u.test(name)||typeof password!=='string'||password.length<8||password.length>128)
    return authJson({error:'用户名需为 2–24 个文字、数字、下划线或短横线，密码需为 8–128 个字符。'},400);
  const key=await nameKey(name);
  let user,revision;
  if(action==='register'){
    const salt=randomKey(),digest=await passwordKey(password,salt);
    user={id:'flora-'+crypto.randomUUID(),name};
    const ok=await env.BUCKET.put(key,JSON.stringify({user,salt,digest}),{onlyIf:new Headers({'If-None-Match':'*'})});
    if(!ok)return authJson({error:'这个用户名已有人使用。'},409);
  }else{
    const obj=await env.BUCKET.get(key),record=obj?await obj.json():null;
    const digest=await passwordKey(password,record?.salt||'unregistered');
    let difference=0;
    const expected=record?.digest||'0'.repeat(64);
    for(let i=0;i<64;i++)difference|=digest.charCodeAt(i)^expected.charCodeAt(i);
    if(!record||difference)return authJson({error:'用户名或密码有误。'},401);
    user=record.user;revision=record.revision;
    if(action==='password'){
      const next=input.newPassword;
      if(typeof next!=='string'||next.length<8||next.length>128||next===password)
        return authJson({error:'请输入与当前密码不同的 8–128 位新密码。'},400);
      const salt=randomKey(),digest=await passwordKey(next,salt);
      revision=crypto.randomUUID();
      const saved=await env.BUCKET.put(key,JSON.stringify({user,salt,digest,revision}),{onlyIf:new Headers({'If-Match':obj.httpEtag})});
      if(!saved)return authJson({error:'密码已在其他设备修改，请重新登录。'},409);
    }
  }
  return authJson({ok:true},200,{'Set-Cookie':await startSession(user,env,revision)});
}
export async function publicAuth(request,env,path){
  try{
    if(path==='previous-garden'){
      if(!['GET','HEAD'].includes(request.method))return authJson({error:'请求方式有误。'},405);
      const priorId=request.headers.get('oai-authenticated-user-id');
      if(!new URL(request.url).hostname.endsWith('.chatgpt.site')||!priorId||
         !request.headers.get('oai-authenticated-user-email')||!await currentUser(request,env))return authJson({},404);
      const key='gardens/v1/'+encodeURIComponent(priorId)+'.json';
      if(request.method==='HEAD'){
        const exists=await env.BUCKET.head(key);
        return new Response(null,{status:exists?200:404,headers:{'Cache-Control':'private, no-store','Vary':'Cookie'}});
      }
      const prior=await env.BUCKET.get(key);
      return prior?authJson(GardenLayout.unpack(await prior.json())):authJson({},404);
    }
    if(!['login','register','logout','password'].includes(path))return authJson({error:'接口不存在。'},404);
    if(request.method!=='POST')return authJson({error:'需要 POST 请求。'},405);
    if(request.headers.get('Origin')!==new URL(request.url).origin)return authJson({error:'请求来源不匹配。'},403);
    if(path==='logout'){
      const key=await sessionKey(request);
      if(key)await env.BUCKET.delete(key);
      return authJson({ok:true},200,{'Set-Cookie':cookie(sessionName,'',0)});
    }
    return await credentials(request,env,path);
  }catch{return authJson({error:'账号服务暂不可用，请稍后再试。'},503)}
}



function checkGarden(items){
  if(!Array.isArray(items)||items.length>800)return false;
  const ids=new Set();
  for(const p of items){
    if(!p||typeof p!=='object')return false;
    for(const field of ['uid','latin','name','date']){
      if(typeof p[field]!=='string'||!p[field].length||p[field].length>400)return false;
    }
    for(const field of ['location','family','note']){
      if(p[field]!=null&&(typeof p[field]!=='string'||p[field].length>2000))return false;
    }
    if(p.palette!=null&&(typeof p.palette!=='object'||Array.isArray(p.palette)||Object.entries(p.palette).some(([k,v])=>!['leaf','bloom'].includes(k)||typeof v!=='string'||!/^#[0-9a-f]{6}$/i.test(v))))return false;
    if(p.model){
      const m=p.model;
      if(!['tree','shrub','flower','grass','rosette','herb'].includes(m.form)||
        ![m.leaf,m.bloom].every(c=>typeof c==='string'&&/^#[a-f0-9]{6}$/i.test(c))||
        ![m.height,m.spread].every(n=>Number.isFinite(n)&&n>=.6&&n<=1.4)||
        (m.arrangement!=null&&!['alternate','opposite','whorled','basal'].includes(m.arrangement))||
        (m.inflorescence!=null&&!['solitary','cluster','spike','none'].includes(m.inflorescence))||
        (m.margin!=null&&!['smooth','toothed'].includes(m.margin))||
        (m.leafAspect!=null&&(!Number.isFinite(m.leafAspect)||m.leafAspect<.65||m.leafAspect>1.5))||
        (m.fact!=null&&(typeof m.fact!=='string'||m.fact.length>240))||
        !Number.isInteger(m.count)||m.count<3||m.count>14||
        (m.petals!=null&&(!Number.isInteger(m.petals)||m.petals<0||m.petals>24)))return false;
    }
    if(!['tree','shrub','flower','grass','rosette','herb'].includes(p.form)||
      !['small','medium','large'].includes(p.size)||!['sill','bench','shelf','pond','path','meadow'].includes(p.zone)||
      typeof p.photo!=='string'||
      !/^data:image\/(jpeg|png|webp);base64,[a-z0-9+/]+=*$/i.test(p.photo))return false;
    if(ids.has(p.uid))return false;
    ids.add(p.uid);
  }
  return true;
}
export async function accountGarden(request,env){
  const send=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'private, no-store','Vary':'Cookie'}});
  const method=request.method;
  if(!['GET','PUT'].includes(method))return send({error:'method'},405);
  try{
    const user=await currentUser(request,env);
    if(!user)return method==='GET'?send({user:null}):send({error:'请先登录账号。'},401);
    const objectKey='gardens/v1/'+encodeURIComponent(user.id)+'.json';
    if(method==='GET'){
      const object=await env.BUCKET.get(objectKey);
      return send({user,version:object?.httpEtag||'new',...GardenLayout.unpack(object?await object.json():[])});
    }
    if(request.headers.get('Origin')!==new URL(request.url).origin)return send({error:'请求来源不匹配。'},403);
    if(!request.headers.get('content-type')?.startsWith('application/json'))return send({error:'需要 JSON 请求。'},415);
    const maxBytes=16*1024*1024;
    if(Number(request.headers.get('content-length'))>maxBytes)return send({error:'花园已超过同步容量。'},413);
    const buffer=await request.arrayBuffer();
    if(buffer.byteLength>maxBytes)return send({error:'花园已超过同步容量。'},413);
    let data;try{data=JSON.parse(new TextDecoder().decode(buffer))}catch{return send({error:'数据格式有误。'},400)}
    if(data?.owner!==user.id)return send({error:'账号已切换，请刷新后重试。'},409);
    if(!checkGarden(data.records)||typeof data.version!=='string'||!(/^(new|"[a-f0-9]{32}")$/i.test(data.version)))return send({error:'花园数据或版本无效。'},400);
    let design=data.design;
    if(design===undefined){
      const old=await env.BUCKET.get(objectKey);
      if(old&&!Array.isArray(await old.json()))return send({error:'请刷新页面，载入新版自由布局。'},409);
      design=GardenLayout.empty();
    }
    if(!Array.isArray(design?.decorations)||design.decorations.length>300||design.decorations.some(p=>!p||typeof p!=='object'))return send({error:'装饰数据无效。'},400);
    const normalized=GardenLayout.unpack({records:data.records,design});
    data.records=normalized.records;design=normalized.design;
    if(!GardenLayout.valid(data.records,design))return send({error:'物品超出布置范围或彼此重叠，请重新摆放。'},400);
    // The inbox and garden share one version. Preserve unopened gifts on ordinary editor saves.
    const current=await env.BUCKET.get(objectKey);
    if((current?.httpEtag||'new')!==data.version)return send({error:'花园已有更新，请刷新后重试。'},409);
    const gifts=current?(await current.json()).gifts||[]:[];
    const serialized=JSON.stringify({records:data.records,design:{scene:design.scene,weather:design.weather,decorations:design.decorations},gifts});
    if(new TextEncoder().encode(serialized).length>maxBytes)return send({error:'花园已超过同步容量。'},413);
    const condition=data.version==='new'?{'If-None-Match':'*'}:{'If-Match':data.version};
    const saved=await env.BUCKET.put(objectKey,serialized,{onlyIf:new Headers(condition),httpMetadata:{contentType:'application/json'}});
    if(!saved)return send({error:'另一台设备已更新花园。已请求最新记录，请重新操作。'},409);
    return send({version:saved.httpEtag});
  }catch{return send({error:'同步服务暂不可用，请稍后重试。'},503)}
}



const displayFields=['name','latin','family','form','size','zone','slot','x','z','potStyle'];
const modelFields=['form','leaf','bloom','height','spread','count','leafShape','crownShape','petals','arrangement','inflorescence','leafAspect','margin','profileVersion','fact'];
export function sharedPlant(plant){
  const entry=Object.fromEntries(displayFields.filter(k=>['string','number'].includes(typeof plant[k])).map(k=>[k,plant[k]]));
  if(plant.palette)entry.palette=Object.fromEntries(['leaf','bloom'].filter(k=>/^#[0-9a-f]{6}$/i.test(plant.palette[k])).map(k=>[k,plant.palette[k]]));
  if(plant.model)entry.model=Object.fromEntries(modelFields.filter(k=>['string','number'].includes(typeof plant.model[k])).map(k=>[k,plant.model[k]]));
  return entry;
}
export async function friendsApi(request,env){
  try{
    const user=await currentUser(request,env);
    if(!user)return authJson({error:'请先登录植迹账号。'},401);
    const db=env.DB,url=new URL(request.url);
    if(request.method==='GET'){
      if(url.searchParams.has('visit')){
        const id=url.searchParams.get('visit');
        const edge=await db.prepare('SELECT * FROM garden_friends WHERE id=? AND accepted=1 AND (sender=? OR recipient=?)').bind(id,user.id,user.id).first();
        if(!edge)return authJson({error:'当前无法访问这座花园。'},403);
        const outgoing=edge.sender===user.id,peer=outgoing?edge.recipient:edge.sender;
        const garden=await env.BUCKET.get('gardens/v1/'+encodeURIComponent(peer)+'.json');
        const {records,design}=GardenLayout.unpack(garden?await garden.json():[]);
        return authJson({name:outgoing?edge.recipient_name:edge.sender_name,plants:records.map(sharedPlant),design});
      }
      const {results}=await db.prepare('SELECT * FROM garden_friends WHERE sender=? OR recipient=? ORDER BY rowid DESC').bind(user.id,user.id).all();
      return authJson({people:results.map(edge=>{
        const outgoing=edge.sender===user.id;
        return {id:edge.id,name:outgoing?edge.recipient_name:edge.sender_name,status:edge.accepted?'friends':outgoing?'sent':'received'};
      })});
    }
    if(request.method!=='POST')return authJson({error:'请求方式有误。'},405);
    if(request.headers.get('Origin')!==url.origin)return authJson({error:'请求来源不匹配。'},403);
    if(!request.headers.get('Content-Type')?.startsWith('application/json'))return authJson({error:'需要 JSON 请求。'},415);
    if(Number(request.headers.get('content-length'))>1024)return authJson({error:'请求过长。'},413);
    const body=await request.json().catch(()=>null);
    if(body?.action==='request'){
      const name=typeof body.name==='string'?body.name.trim().normalize('NFKC'):'';
      if(!name||name.length>48)return authJson({error:'请输入好友的完整用户名。'},400);
      if(!await authQuota(request,env,'friend-request'))return authJson({error:'申请太频繁，请稍后再试。'},429);
      const object=await env.BUCKET.get(await nameKey(name)),peer=object?(await object.json()).user:null;
      if(!peer)return authJson({error:'未找到这个用户名。'},404);
      if(peer.id===user.id)return authJson({error:'这是你自己的账号。'},400);
      const result=await db.prepare('INSERT INTO garden_friends(id,sender,recipient,sender_name,recipient_name) VALUES (?,?,?,?,?) ON CONFLICT DO NOTHING').bind(crypto.randomUUID(),user.id,peer.id,user.name,peer.name).run();
      if(!result.meta.changes)return authJson({error:'已有好友关系或申请，请查看列表。'},409);
      return authJson({ok:true},201);
    }
    if(typeof body?.id!=='string'||body.id.length!==36)return authJson({error:'申请无效。'},400);
    const mutations={
      accept:'UPDATE garden_friends SET accepted=1 WHERE id=? AND recipient=? AND accepted=0',
      decline:'DELETE FROM garden_friends WHERE id=? AND recipient=? AND accepted=0',
      cancel:'DELETE FROM garden_friends WHERE id=? AND sender=? AND accepted=0',
      remove:'DELETE FROM garden_friends WHERE id=? AND ? IN (sender,recipient) AND accepted=1'
    };
    if(!Object.hasOwn(mutations,body.action))return authJson({error:'操作无效。'},400);
    const result=await db.prepare(mutations[body.action]).bind(body.id,user.id).run();
    return result.meta.changes?authJson({ok:true}):authJson({error:'关系已变更，请刷新列表。'},409);
  }catch{return authJson({error:'好友服务暂不可用，请稍后重试。'},503)}
}




async function giftGarden(env,id){
  const key='gardens/v1/'+encodeURIComponent(id)+'.json',object=await env.BUCKET.get(key);
  const data=object?await object.json():[];
  return {key,object,...GardenLayout.unpack(data),gifts:data.gifts||[]};
}
async function saveGiftGarden(env,garden){
  const {key,object,records,design,gifts}=garden,json=JSON.stringify({records,design,gifts});
  if(new TextEncoder().encode(json).length>16*1024*1024)return authJson({error:'花园存储空间已满。'},413);
  const saved=await env.BUCKET.put(key,json,{onlyIf:new Headers(object?{'If-Match':object.httpEtag}:{'If-None-Match':'*'}),httpMetadata:{contentType:'application/json'}});
  return saved?authJson({ok:true}):authJson({error:'花园刚有更新，请刷新花友列表再试。'},409);
}
export async function giftsApi(request,env){
  try{
    const user=await currentUser(request,env);
    if(!user)return authJson({error:'请先登录植迹账号。'},401);
    if(request.method==='GET'){
      const {gifts}=await giftGarden(env,user.id);
      return authJson({gifts:gifts.map(({id,from,plant})=>({id,from,plant}))});
    }
    if(request.method!=='POST')return authJson({error:'请求方式有误。'},405);
    if(request.headers.get('Origin')!==new URL(request.url).origin)return authJson({error:'请求来源不匹配。'},403);
    if(!request.headers.get('Content-Type')?.startsWith('application/json'))return authJson({error:'需要 JSON 请求。'},415);
    if(Number(request.headers.get('Content-Length'))>250000)return authJson({error:'请求过大。'},413);
    const raw=await request.text();
    if(raw.length>250000)return authJson({error:'请求过大。'},413);
    let b;try{b=JSON.parse(raw)}catch{return authJson({error:'无效请求。'},400)}
    if(typeof b?.id!=='string'||b.id.length!==36)return authJson({error:'编号无效。'},400);
    if(b.action==='send'){
      const edge=await env.DB.prepare('SELECT * FROM garden_friends WHERE id=? AND accepted=1 AND (sender=? OR recipient=?)').bind(b.id,user.id,user.id).first();
      if(!edge)return authJson({error:'请先成为花友。'},403);
      const own=await giftGarden(env,user.id),source=own.records.find(p=>p.uid===b.uid);
      if(!source)return authJson({error:'这株植物已不在花园中。'},404);
      if(!await authQuota(request,env,'gift'))return authJson({error:'赠送太频繁，请稍后再试。'},429);
      const garden=await giftGarden(env,edge.sender===user.id?edge.recipient:edge.sender);
      if(garden.gifts.length>=24)return authJson({error:'对方的礼物盒已满。'},409);
      if(garden.gifts.some(g=>g.sender===user.id&&g.source===source.uid))return authJson({error:'这株分株正在等待对方领取。'},409);
      const plant=sharedPlant(source);
      for(const key of ['slot','x','z'])delete plant[key];
      garden.gifts.push({id:crypto.randomUUID(),from:user.name,sender:user.id,source:source.uid,plant});
      return saveGiftGarden(env,garden);
    }
    if(!['accept','decline'].includes(b.action))return authJson({error:'操作无效。'},400);
    const garden=await giftGarden(env,user.id),idx=garden.gifts.findIndex(g=>g.id===b.id);
    if(idx<0)return authJson({error:'这份礼物已经处理。'},409);
    const gift=garden.gifts[idx];
    if(b.action==='accept'){
      if(garden.records.length>=800)return authJson({error:'花园已满。'},409);
      if(!GardenLayout.zones.includes(b.zone)||typeof b.cover!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(b.cover))return authJson({error:'分株封面或位置无效。'},400);
      const p={...gift.plant,uid:crypto.randomUUID(),zone:b.zone,photo:b.cover,gift:true,date:new Date().toISOString().slice(0,10)};
      Object.assign(p,GardenLayout.place(p,garden.records.concat(garden.design.decorations)));
      garden.records.push(p);
    }
    garden.gifts.splice(idx,1);
    return saveGiftGarden(env,garden);
  }catch{return authJson({error:'礼物盒暂不可用，请稍后重试。'},503)}
}

export async function identify(request, env, upstream = fetch) {
  const reply = (data, status = 200) => Response.json(data, {status, headers: {'cache-control':'no-store'}});
  if (request.method !== 'POST') return reply({error:'请提交一张植物照片。'},405);
  const origin = request.headers.get('origin');
  if (origin && origin !== new URL(request.url).origin) return reply({error:'请求来源不匹配。'},403);
  const key = env.PLANTNET_API_KEY || request.headers.get('x-plantnet-key');
  if (!key) return reply({code:'key',error:'请连接 Pl@ntNet 以开始识别。'},401);
  if (request.headers.get('content-type') !== 'image/jpeg') return reply({error:'请使用 JPEG 图像。'},415);
  const photo = await request.blob();
  if (!photo.size || photo.size > 4_000_000) return reply({error:'照片大小超出范围，请换一张。'},400);
  const form = new FormData();
  form.append('images',photo,'plant.jpg');
  const url = new URL('https://my-api.plantnet.org/v2/identify/all');
  url.search = new URLSearchParams({'api-key':key,lang:'zh','nb-results':'5'}).toString();
  try {
    const res = await upstream(url,{method:'POST',body:form,signal:AbortSignal.timeout(25000)});
    if ([401,403].includes(res.status)) return reply({code:env.PLANTNET_API_KEY?'config':'key',error:'识别密钥无效或权限不足，请检查 Pl@ntNet 配置。'},403);
    if (res.status === 404) return reply({results:[]});
    if (res.status === 429) return reply({error:'识别配额已用完，请稍后重试。'},429);
    if (!res.ok) return reply({error:'识别服务暂时不可用。'},502);
    const data = await res.json();
    const results = (data.results || []).filter(r=>r.species?.scientificNameWithoutAuthor).map(r=>({
      latin:r.species.scientificNameWithoutAuthor, name:r.species.commonNames?.[0] || r.species.scientificNameWithoutAuthor,
      score:r.score, family:r.species.family?.scientificNameWithoutAuthor || ''
    }));
    return reply({results});
  } catch {return reply({error:'连接识别服务超时或失败，请重试。'},503)}
}

// Geometry and shading are owned by the garden renderer. The model chooses only
// botanical traits and named swatches from the garden's existing palette.
const forms = ['tree', 'shrub', 'flower', 'grass', 'rosette', 'herb'];
const leafShapes = ['oval','lanceolate','needle','fan','palmate','heart','succulent'];
const crownShapes = ['upright','rounded','spreading','weeping','conical'];
const foliage = {
  meadow: '#70a05c', forest: '#568357', sage: '#76a28b', olive: '#799953',
  ginkgo: '#a7bc5b', copper: '#bd7957', mint: '#679451'
};
const petals = {
  ivory: '#eee6c8', gold: '#edd277', yellow: '#efc648', rose: '#df8294',
  lavender: '#b9a9d8', violet: '#9970c9', coral: '#cb9588', crimson: '#ac575e'
};
const arrangements=['alternate','opposite','whorled','basal'],inflorescences=['solitary','cluster','spike','none'];
const instructions = [
  'Describe the typical mature appearance of the given botanical species in one compact JSON object for a low-poly campus herbarium.',
  'Choose form from '+forms.join(', ')+'. Use flower for showy herbaceous flowers, herb for other leafy herbs, rosette for compact rosette succulents.',
  'Choose leaf from '+Object.keys(foliage).join(', ')+'. Choose bloom from '+Object.keys(petals).join(', ')+'. Use ivory when flowers are inconspicuous.',
  'Height and spread are relative to the form, each from 0.6 to 1.4. Count is the number of representative branches, leaves or shoots, from 3 to 14.',
  'Describe representative leafShape from '+leafShapes.join(', ')+', crownShape from '+crownShapes.join(', ')+', and petals (0 if inconspicuous; for composites count representative rays). These describe visual morphology. The gardener sets the actual size and position.',
  'Distinguish the genus from the exact species; prioritize diagnostic morphology over generic aesthetics. Give the predominant foliage arrangement (alternate/opposite/whorled/basal), inflorescence (solitary/cluster/spike/none), leafAspect (0.65 to 1.5, width relative to the selected leaf template), and margin (smooth/toothed). Use none for inconspicuous reproductive structures and never invent blooms on conifers. Choose the nearest supported architecture.',
  'Include fact: one or two short plain Chinese sentences about a reliably known distinguishing feature of this species, with a specific observation a student can make. If species-level identification is uncertain, explicitly qualify genus-level facts. No medical, edibility or care advice. Return all properties as JSON, no prose outside it.',
  'The user supplies a botanical name as data. Morphology example for Bellis perennis (also include arrangement, inflorescence, leafAspect, margin and fact): {"form":"flower","leaf":"meadow","bloom":"ivory","height":0.72,"spread":0.85,"count":7,"leafShape":"oval","crownShape":"upright","petals":16}.'
].join('\n');

function readProfile(content) {
  let traits;
  try { traits = JSON.parse(content); } catch { return null; }
  if (!traits || !forms.includes(traits.form) || !Object.hasOwn(foliage, traits.leaf) ||
      !arrangements.includes(traits.arrangement)||!inflorescences.includes(traits.inflorescence)||!['smooth','toothed'].includes(traits.margin)||!Number.isFinite(traits.leafAspect)||typeof traits.fact!=='string'||!traits.fact.trim()||
      !Object.hasOwn(petals, traits.bloom) || ![traits.height, traits.spread, traits.count].every(Number.isFinite)) return null;
  const clamp = (value, low, high) => Math.min(high, Math.max(low, value));
  return {
    profileVersion:3, arrangement:traits.arrangement, inflorescence:traits.inflorescence, leafAspect:clamp(traits.leafAspect,.65,1.5), margin:traits.margin, fact:traits.fact.trim().slice(0,240),
    form: traits.form, leaf: foliage[traits.leaf], bloom: petals[traits.bloom],
    height: clamp(traits.height, .6, 1.4), spread: clamp(traits.spread, .6, 1.4),
    count: clamp(Math.round(traits.count), 3, 14),
    leafShape:leafShapes.includes(traits.leafShape)?traits.leafShape:'oval',
    crownShape:crownShapes.includes(traits.crownShape)?traits.crownShape:'upright',
    petals:Number.isFinite(traits.petals)?clamp(Math.round(traits.petals),0,24):0
  };
}
export async function modelPlant(request, env, upstream = fetch) {
  const reply = (data, status = 200) => Response.json(data, {status, headers:{'cache-control':'no-store'}});
  if (request.method !== 'POST') return reply({error:'method'}, 405);
  const origin = request.headers.get('origin');
  if (origin && origin !== new URL(request.url).origin) return reply({error:'origin'}, 403);
  const input = await request.json().catch(()=>null);
  if (typeof input?.latin !== 'string' || !input.latin.trim() || input.latin.length > 160) return reply({error:'species'}, 400);
  if (!env.DEEPSEEK_API_KEY) return reply({reason:'unconfigured'}, 503);
  try {
    const response = await upstream('https://api.deepseek.com/chat/completions', {
      method:'POST', headers:{Authorization:'Bearer '+env.DEEPSEEK_API_KEY,'Content-Type':'application/json'},
      signal:AbortSignal.timeout(85000),
      body:JSON.stringify({
        model:'deepseek-v4-pro', thinking:{type:'enabled'}, response_format:{type:'json_object'},
        max_tokens:3200,
        messages:[{role:'system',content:instructions},{role:'user',content:input.latin.trim()}]
      })
    });
    if (!response.ok) {
      const reasons = {401:'credentials',403:'credentials',402:'billing',429:'rate_limit'};
      return reply({reason:reasons[response.status] || 'upstream'}, 503);
    }
    const data = await response.json();
    const model = readProfile(data.choices?.[0]?.message?.content);
    return model ? reply({provider:'DeepSeek',model}) : reply({reason:'invalid'}, 502);
  } catch {
    return reply({reason:'unavailable'}, 503);
  }
}

